<?php
declare(strict_types=1);
require __DIR__.'/v10-lib.php';
function web_lead_limit(string $bucket,int $maximum,int $window):void{$dir=v10_storage_dir('rate-limits');$path=$dir.'/'.hash('sha256',$bucket).'.json';$fp=fopen($path,'c+');if(!$fp)throw new RuntimeException('Rate-limit storage unavailable');try{if(!flock($fp,LOCK_EX))throw new RuntimeException('Rate-limit storage unavailable');$raw=stream_get_contents($fp);$now=time();$hits=array_values(array_filter(json_decode($raw?:'[]',true)?:[],fn($v)=>is_int($v)&&$v>$now-$window));if(count($hits)>=$maximum)throw new OverflowException('Too many submissions. Please try again later.');$hits[]=$now;ftruncate($fp,0);rewind($fp);fwrite($fp,json_encode($hits));fflush($fp);flock($fp,LOCK_UN);}finally{fclose($fp);}}
$key=(string)($_GET['k']??$_POST['k']??'');$st=db()->prepare('SELECT * FROM v10_web_forms WHERE public_key=? AND active=1 LIMIT 1');$st->execute([$key]);$form=$st->fetch();if(!$form){http_response_code(404);exit('Form not found');}$fields=v10_json_decode((string)$form['fields_json']);$done=false;$error='';if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){try{if(!empty($_POST['website']))throw new RuntimeException('Spam');$name=trim((string)($_POST['name']??''));$phone=trim((string)($_POST['phone']??''));$email=trim((string)($_POST['email']??''));$message=trim((string)($_POST['message']??''));if(!$name)throw new RuntimeException('Name required');$ip=client_ip();web_lead_limit('ip:'.$ip,20,3600);web_lead_limit('form:'.$form['id'],100,3600);web_lead_limit('form-ip:'.$form['id'].':'.$ip,5,600);db()->prepare("INSERT INTO leads(company_id,title,customer_name,phone,email,source,stage,notes) VALUES(?,?,?, ?,?,'web_form','new',?)")->execute([$form['company_id'],'Web inquiry · '.$name,$name,$phone?:null,$email?:null,$message]);$done=true;}catch(Throwable $e){if($e instanceof OverflowException)http_response_code(429);$error=$e->getMessage();}}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{font-family:Tahoma,Arial;background:#faf7f0;color:#173f35;margin:0}.form{max-width:620px;margin:auto;padding:24px}input,textarea{width:100%;box-sizing:border-box;padding:12px;margin:6px 0 12px;border:1px solid #ddd;border-radius:8px}button{background:#173f35;color:#fff;border:0;border-radius:8px;padding:12px 18px}</style></head><body><main class="form"><h2><?=e($form['title_fa'])?></h2><?php if($done):?><p>درخواست شما ثبت شد.</p><?php else:?><?php if($error):?><p><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="k" value="<?=e($key)?>"><input type="text" name="website" style="display:none" tabindex="-1" autocomplete="off"><?php if(in_array('name',$fields,true)):?><label>نام</label><input name="name" required><?php endif;?><?php if(in_array('phone',$fields,true)):?><label>تلفن</label><input name="phone"><?php endif;?><?php if(in_array('email',$fields,true)):?><label>ایمیل</label><input name="email" type="email"><?php endif;?><?php if(in_array('message',$fields,true)):?><label>پیام</label><textarea name="message"></textarea><?php endif;?><button>ارسال</button></form><?php endif;?></main></body></html>
